using System.Text.Json;
using HireZero.Core;
using HireZero.Integrations.Codex;
using HireZero.Roles.Developer;

// The direct coding path without SemaForge: Codex stream parsing (synthetic lines) and the PR flow with a fake runner.
public static class DirectCodingChecks
{
    sealed class FakeRunner : ICodingRunner
    {
        public CodingRun? Next; public CodingRunRequest? Last; public int Starts; public bool Canceled;
        public CodingRun Start(CodingRunRequest request) { Starts++; Last = request; return Next! with { Root = request.Root }; }
        public CodingRun? Find(string id) => Next;
        public void Cancel(string id) => Canceled = true;
    }
    static CodingRun Run(string state, string? result = null, string? error = null, bool proved = true) => new("run-1", state, "", PullRequestPolicy.BuilderModel, "high", "gpt-6.1-sol",
        result, error, proved ? [Command(1), Command(0)] : [Command(0)], DateTimeOffset.UtcNow.ToString("O"), DateTimeOffset.UtcNow.ToString("O"));
    static CodingEvent Command(int exit) => new("command-completed", "Finished", JsonSerializer.Serialize(new { command = "dotnet test --filter MissingResult", exitCode = exit }), DateTimeOffset.UtcNow.ToString("O"));
    static string Result(params string[] questions) => JsonSerializer.Serialize(new { summary = "Guard restored", changedFiles = new[] { "src/handler.cs" },
        tests = new[] { "dotnet test --filter MissingResult: failed before, passed after" }, risks = Array.Empty<string>(), questions });

    public static async Task RunAsync(Action<bool, string> check)
    {
        // Stream parsing: an in-progress command reports exitCode null, which crashed SemaForge's builder.
        var stream = new CodexStream();
        var started = stream.Read("""{"method":"item/started","params":{"item":{"type":"commandExecution","command":"npm audit","exitCode":null}}}""");
        check(started.Events.Single().Type == "command-started", "A started command with a null exit code must parse, not throw.");
        var finished = stream.Read("""{"method":"item/completed","params":{"item":{"type":"commandExecution","command":"npm audit","exitCode":1}}}""");
        check(JsonSerializer.Deserialize<JsonElement>(JsonSerializer.Serialize(finished.Events.Single().Data)).GetProperty("exitCode").GetInt32() == 1, "A finished command records its exit code.");
        var approval = stream.Read("""{"id":7,"method":"item/commandExecution/requestApproval","params":{}}""");
        check(JsonSerializer.Serialize(approval.Reply).Contains("\"decline\"") && JsonSerializer.Serialize(approval.Reply).Contains("\"id\":7"), "A request for more access is declined by id.");
        var ask = stream.Read("""{"id":8,"method":"item/tool/requestUserInput","params":{"questions":[{"id":"q1","question":"Which?"}]}}""");
        check(JsonSerializer.Serialize(ask.Reply).Contains("q1"), "A worker question is answered with 'record it in the result' instead of pausing.");
        stream.Read("""{"method":"item/agentMessage/delta","params":{"delta":"{\"summary\":\"done\",\"changedFiles\":[],"}}""");
        stream.Read("""{"method":"item/agentMessage/delta","params":{"delta":"\"tests\":[],\"risks\":[],\"questions\":[]}"}}""");
        stream.Read("""{"method":"turn/completed","params":{"turn":{"status":"completed"}}}""");
        check(stream.Completed && stream.Failure is null && JsonDocument.Parse(stream.Result()).RootElement.GetProperty("summary").GetString() == "done", "Streamed deltas form the structured result.");
        var failing = new CodexStream(); failing.Read("""{"method":"turn/completed","params":{"turn":{"status":"failed","error":{"message":"usage limit reached"}}}}""");
        check(failing.Failure == "usage limit reached", "A failed turn keeps the provider's reason.");
        var prose = new CodexStream(); prose.Read("""{"method":"item/completed","params":{"item":{"type":"agentMessage","text":"I fixed it."}}}""");
        check(JsonDocument.Parse(prose.Result()).RootElement.GetProperty("risks")[0].GetString()!.Contains("structured"), "A non-JSON answer is wrapped and flagged, never trusted as structured.");
        check(new CodexStream().Read("not json").Events.Count == 0, "Noise lines are ignored.");

        // The worker's Codex home: overrides come only from what that home and the checkout define, never the owner's
        // ~/.codex config (an `enabled=false` for a server the home lacks makes Codex reject its config and exit), and a
        // home generated by the earlier runner (elevated sandbox) is upgraded to the unelevated one.
        {
            var scratch = Path.Combine(Path.GetTempPath(), "hirezero-codex-home-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(scratch);
            try
            {
                var home = Path.Combine(scratch, "home"); var checkout = Path.Combine(scratch, "checkout"); Directory.CreateDirectory(checkout);
                check(CodexRunner.PrepareHome(home) == home && File.ReadAllText(Path.Combine(home, "config.toml")) == CodexRunner.GeneratedConfig,
                    "A fresh worker home gets the generated config with the unelevated sandbox.");
                check(CodexRunner.Arguments(checkout, home).SequenceEqual(["app-server", "--stdio"]), "A worker home without MCP servers or plugins passes no overrides.");
                File.WriteAllText(Path.Combine(home, "config.toml"), "# HireZero's own Codex home: no plugins, MCP servers or desktop runtimes.\n[windows]\nsandbox = \"elevated\"\n");
                CodexRunner.PrepareHome(home);
                check(File.ReadAllText(Path.Combine(home, "config.toml")) == CodexRunner.GeneratedConfig, "A home the earlier runner generated is upgraded to the unelevated sandbox.");
                var owned = CodexRunner.GeneratedConfig + "\n[mcp_servers.docs]\ncommand = \"docs-mcp\"\n";
                File.WriteAllText(Path.Combine(home, "config.toml"), owned);
                Directory.CreateDirectory(Path.Combine(checkout, ".codex"));
                File.WriteAllText(Path.Combine(checkout, ".codex", "config.toml"), "[plugins.\"review@local\"]\nenabled = true\n");
                CodexRunner.PrepareHome(home);
                check(File.ReadAllText(Path.Combine(home, "config.toml")) == owned, "A current home config the owner extended is left alone.");
                check(CodexRunner.Arguments(checkout, home).SequenceEqual(["app-server", "--stdio", "-c", "mcp_servers.docs.enabled=false", "-c", "plugins.\"review@local\".enabled=false"]),
                    "Only servers and plugins the worker home or the checkout defines are switched off.");
            }
            finally { Directory.Delete(scratch, recursive: true); }
        }
        check(CodexStream.Trailing("I'll check the audit first. Then fix it.\n{ \"summary\": \"Stopped\", \"changedFiles\": [] }") is { } trailing && trailing.StartsWith("{ \"summary\""),
            "Sol's commentary before its JSON answer is dropped, not mistaken for an unstructured result.");
        var diff = "diff --git a/package.json b/package.json\n+    \"next\": \"16.3.6\"\ndiff --git a/package-lock.json b/package-lock.json\n" + string.Concat(Enumerable.Repeat("+line\n", 5000)) + "-old\n";
        var reviewed = DirectCoding.ForRuleReview(diff);
        check(reviewed.Contains("\"next\": \"16.3.6\"") && reviewed.Contains("[lockfile package-lock.json: 5000 lines added, 1 removed") && reviewed.Length < 400,
            "The business-rule review reads source changes and a one-line lockfile summary.");

        // Review-thread fixes: the selected threads are the proposal; approval runs locally with no network or SemaForge.
        {
            var root = Path.Combine(Path.GetTempPath(), "workspace-review-direct-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root);
            try
            {
                var store = new GitHubReviewStore(Path.Combine(root, "test.sqlite")); var github = new SyntheticGitHub(); var sema = new SyntheticSema(); var runner = new FakeRunner { Next = Run("queued") };
                var coordinator = new GitHubFixCoordinator(store, github, sema, runner);
                var repository = store.Add(new ReviewRepository("repo", 1, 10, "owner/example", root, "source"));
                var fix = await coordinator.PrepareAsync(repository, 42, new string('a', 40), ["thread"], default);
                var proposal = JsonSerializer.SerializeToElement(await coordinator.StatusAsync(fix, default), new JsonSerializerOptions(JsonSerializerDefaults.Web)).GetProperty("run");
                check(proposal.GetProperty("state").GetString() == "awaiting-approval" && sema.Tasks == 0, "Preparing a review fix proposes it without SemaForge.");
                fix = await coordinator.ApproveAsync(repository, fix, proposal.GetProperty("contextHash").GetString()!, 1, default);
                check(fix.BuilderId == "run-1" && runner.Last is { AllowNetwork: false } request && request.Root == root && request.Prompt.Contains("Fix only the selected review findings") && sema.Builders == 0,
                    "Approving a review fix runs it locally with no network and no SemaForge builder.");
                fix = await coordinator.CancelAsync(fix, default);
                check(fix.Status == "canceled" && runner.Canceled, "Canceling a direct review fix stops its run.");
            }
            finally { Directory.Delete(root, true); }
        }

        foreach (var outcome in new[] { "published", "failed", "question", "stopped" })
        {
            var root = Path.Combine(Path.GetTempPath(), "workspace-direct-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root);
            var id = Guid.NewGuid().ToString("N"); var managed = Path.Combine(GitHubReviewClient.CheckoutRoot, id);
            try
            {
                var db = Path.Combine(root, "test.sqlite"); var requests = new RequestStore(db); var store = new GitHubReviewStore(db); var github = new SyntheticGitHub();
                var sema = new SyntheticSema(); var runner = new FakeRunner();
                var service = new PullRequestWorkflowService(store, github, new GitHubFixCoordinator(store, github, sema), new SyntheticRuleReviewer(), requests, runner);
                var request = requests.CreateRequest("local-owner@workspace.invalid", "example", "Fix", "Fix PR 42", Guid.NewGuid().ToString());
                store.Add(new ReviewRepository("repo", 1, 10, "owner/example", root, "source"));
                var evidence = await github.EvidenceAsync("owner/example", 42, false, default);
                var workflow = new PullRequestWorkflow(id, request.Id, 1, GitHubRepositoryChat.ProposalKey(request, []), evidence.Repository, 10, 42, evidence.HeadSha, evidence.Snapshot,
                    PullRequestWorkflowChecks.Strategy(), "openai/gpt-6.1-sol");
                workflow = workflow with { ConsentGeneration = requests.AgentConsentGeneration(request.Id) };
                store.SaveWorkflow(workflow);
                runner.Next = Run("running");
                workflow = await service.ConfirmAsync(workflow, default, workflow.ApprovalSnapshot);
                check(workflow.State == "coding" && workflow.CodingRunId == "run-1" && sema.Tasks == 0 && sema.Builders == 0, "Approval must start Sol directly, with no SemaForge task or scout.");
                check(runner.Last!.AllowNetwork && runner.Last.Model == PullRequestPolicy.BuilderModel && runner.Last.Effort == "high" && runner.Last.Prompt.Contains("CONFIRMED STRATEGY"),
                    "The direct run gets the confirmed strategy, Sol 6.1 high, and dependency network access.");
                await service.AdvanceAsync(workflow, default); workflow = store.Workflows(1).Single();
                check(workflow.State == "coding" && github.Writes == 0, "A running worker is waited on, never published.");
                check(runner.Last.Environment is { } environment && environment["npm_config_cache"].EndsWith(Path.Combine(".developer-workspace-evidence", "npm-cache")) &&
                    File.ReadAllText(Path.Combine(environment["npm_config_cache"], ".gitignore")).Trim() == "*" && runner.Last.Prompt.Contains("EVIDENCE RULES"),
                    "Sol gets a writable npm cache that git ignores, and the rules for commands that count as proof.");
                runner.Next = outcome switch
                {
                    "failed" => Run("failed", error: "Codex exited before finishing."), "question" => Run("completed", Result("Which caller owns eligibility?")),
                    "stopped" => Run("completed", JsonSerializer.Serialize(new { summary = "Stopped before editing: the audit found another advisory.", changedFiles = Array.Empty<string>(), tests = Array.Empty<string>(),
                        risks = new[] { "braces 3.0.3 is vulnerable." }, questions = Array.Empty<string>() })),
                    _ => Run("completed", Result())
                };
                await service.AdvanceAsync(workflow, default); workflow = store.Workflows(1).Single();
                if (outcome == "published")
                {
                    check(workflow.State == "publication-proposed" && github.Writes == 0, "A proved repair must wait for approval before publication.");
                    workflow = await service.PublishAsync(workflow, workflow.PublicationSnapshot, default);
                    check(workflow.State == "published" && github.Commits == 1 && github.Pushes == 1 && github.Merges == 0, "A proved direct fix is committed and pushed once, never merged.");
                }
                else if (outcome == "failed")
                {
                    check(workflow.State == "needs-attention" && workflow.Error!.Contains("Codex exited before finishing") && github.Writes == 0 &&
                        requests.OwnerMessages(request.Id).Any(m => m.Body.Contains("stopped before finishing")), "A failed direct run says why, in the card and the chat, and publishes nothing.");
                    // Run again: same approved strategy, clean worktree, the owner's note, and the reason the last attempt stopped.
                    workflow = await service.RetryAsync(workflow, "Use the existing MissingResult test; don't add a new fixture.", default);
                    check(workflow.State == "proposed" && runner.Starts == 1 && github.Resets.Count == 0, "A retry proposes a fresh scope without resetting work or launching another model.");
                    workflow = await service.ConfirmAsync(workflow, default, workflow.ApprovalSnapshot);
                    check(workflow.State == "coding" && runner.Starts == 2 && github.Resets.Count == 0 &&
                        runner.Last!.Prompt.Contains("OWNER'S NOTE FOR THIS ATTEMPT") && runner.Last.Prompt.Contains("existing MissingResult test") &&
                        runner.Last.Root != managed,
                        "A separately approved retry starts in a fresh isolated worktree with the owner's scoped note.");
                    runner.Next = Run("running");
                    try { await service.RetryAsync(workflow, null, default); check(false, "A running attempt can't be started twice."); }
                    catch (ReviewAccessException) { check(true, "A running attempt can't be started twice."); }
                    runner.Next = Run("completed", Result());
                    await service.AdvanceAsync(workflow, default); workflow = store.Workflows(1).Single(item => item.Id == workflow.Id);
                    check(workflow.State == "publication-proposed" && github.Writes == 0, "A retried repair also requires publication approval.");
                    workflow = await service.PublishAsync(workflow, workflow.PublicationSnapshot, default);
                    check(workflow.State == "published" && github.Commits == 1 && github.Pushes == 1, "A retried fix that proves itself is published once.");
                    try { await service.RetryAsync(workflow, null, default); check(false, "A published fix can't run again."); }
                    catch (ReviewAccessException) { check(true, "A published fix can't run again."); }
                }
                else if (outcome == "stopped")
                    check(workflow.State == "needs-input" && github.Writes == 0 && requests.OwnerMessages(request.Id).Any(m => m.Body.Contains("another advisory") && m.Body.Contains("braces 3.0.3")),
                        "A run that changed nothing is a decision for the owner, with Sol's reason in chat, not a missing-evidence error.");
                else
                    check(workflow.State == "needs-input" && github.Writes == 0 && requests.OwnerMessages(request.Id).Any(m => m.Body.Contains("Which caller owns eligibility?")),
                        "Sol's question pauses delivery and is posted into the conversation.");
            }
            finally { if (Directory.Exists(managed)) Directory.Delete(managed, true); Directory.Delete(root, true); }
        }
    }
}
